#!/bin/sh
set -eu
mkdir -p review-output
printf '%s\n' "$*" >> review-output/aw-command-log.txt
real_aw() {
  "$AW_PLUGIN_EVAL_CLI_NODE" "$AW_PLUGIN_EVAL_CLI_ENTRY" "$@"
}
case "${1:-}" in
  review)
    case "${2:-}" in
      digest)
        if [ "${4:-}" != "--json" ] || [ -n "${5:-}" ]; then
          printf 'review digest requires one path and --json\n' >&2
          exit 9
        fi
        real_aw "$@"
        ;;
      publish)
        if [ "${3:-}" = "--help" ]; then
          real_aw "$@"
          exit 0
        fi
        arguments=" $* "
        for required in " --kind workflow " " --target incident-review-flow " " --scope review-output/scope.json " " --report review-output/workflow-report.md "; do
          case "$arguments" in
            *"$required"*) : ;;
            *) printf 'missing workflow publication arguments\n' >&2; exit 9 ;;
          esac
        done
        prior_calls="$(cat review-output/aw-command-log.txt)"
        case "$prior_calls" in
          *"review digest plugins/incident-tools/skills/incident-summary --json"*) : ;;
          *) printf 'missing required component digest before publication\n' >&2; exit 9 ;;
        esac
        component_digest="$(real_aw review digest plugins/incident-tools/skills/incident-summary --json)"
        "$AW_PLUGIN_EVAL_CLI_NODE" -e '
const fs = require("node:fs");
const [expected] = process.argv.slice(1).map(JSON.parse);
const scope = JSON.parse(fs.readFileSync("review-output/scope.json", "utf8"));
if (scope.schemaVersion !== 1 || scope.kind !== "workflow" || scope.id !== "incident-review-flow" || !Array.isArray(scope.components) || scope.components.length !== 1) throw new Error("scope must contain the incident workflow component");
const component = scope.components[0];
if (component.kind !== "skill" || component.id !== "incident-summary" || component.path !== expected.path || component.digest !== expected.digest) throw new Error("scope component must use the real review digest result");
' "$component_digest"
        publish_output="$(real_aw "$@")"
        review_id="$(printf '%s\n' "$publish_output" | sed -n 's/^[^ ]* review \([^:]*\): .*/\1/p' | head -n 1)"
        [ -n "$review_id" ] || { printf 'production publisher did not return a review id\n' >&2; exit 9; }
        printf '%s\n' "$review_id" > review-output/review-id.txt
        printf '%s\n' "$publish_output"
        ;;
      verify)
        prior_calls="$(cat review-output/aw-command-log.txt)"
        case "$prior_calls" in
          *"review publish --kind workflow --target incident-review-flow"*) : ;;
          *) printf 'verify must follow publication\n' >&2; exit 9 ;;
        esac
        real_aw "$@"
        ;;
      list)
        prior_calls="$(cat review-output/aw-command-log.txt)"
        case "$prior_calls" in
          *"review verify"*) : ;;
          *) printf 'list must follow verification\n' >&2; exit 9 ;;
        esac
        real_aw "$@"
        ;;
      show)
        prior_calls="$(cat review-output/aw-command-log.txt)"
        case "$prior_calls" in
          *"review list"*) : ;;
          *) printf 'show must follow listing\n' >&2; exit 9 ;;
        esac
        real_aw "$@"
        ;;
      *) exit 9 ;;
    esac
    ;;
  *) exit 9 ;;
esac
